    assert!((admit_ambient(clean.clone(), String::from("OldCache/cache/;!services;:D;:Other")) == ""));
    assert!((admit_ambient(clean.clone(), String::from("OldStore/db/;!services;:D")) == admit_ambient(clean.clone(), String::from("OldStore/db/"))));
